#!/usr/bin/env python3
"""
SEL4ME Lesson Converter
Converts captured Navigate 360 lesson HTML + quiz data into
standalone interactive HTML lessons with Maine DOE / EnGiNE-inspired branding.

Usage:
    python sel4me_converter.py --lesson-html path/to/lesson.html \
                                --data path/to/SEL4ME_all_lesson_data.json \
                                --catalog path/to/sel4me_full_catalog.json \
                                --output path/to/output/
"""

import json, re, os, sys, argparse
from urllib.parse import quote as url_quote
from bs4 import BeautifulSoup
from html import escape, unescape


# ============================================================
# STORYLINE MODULE EMBEDS
# ============================================================
# Same rule as mirror_storyline.py and build_module_inventory.py — keep identical.
def safe_module_folder(module_id):
    """Spaces -> underscores, then drop any char not in A-Za-z0-9._-"""
    return re.sub(r'[^A-Za-z0-9._-]', '', module_id.replace(' ', '_'))


MODULE_ENTRY_CANDIDATES = ['story.html', 'story_html5.html', 'index.html']


def find_module_entry(modules_dir, module_id):
    """Entry file for a mirrored module as '<safe_folder>/story.html', or None if not mirrored."""
    if not modules_dir or not module_id:
        return None
    folder_name = safe_module_folder(module_id)
    folder = os.path.join(modules_dir, folder_name)
    if not folder_name or not os.path.isdir(folder):
        return None
    candidates = []
    manifest = os.path.join(folder, 'mirror-manifest.json')
    if os.path.isfile(manifest):
        try:
            with open(manifest, 'r', encoding='utf-8') as f:
                entry = json.load(f).get('entry')
            if entry and '/' not in entry and '\\' not in entry:
                candidates.append(entry)
        except (OSError, ValueError):
            pass
    candidates += [c for c in MODULE_ENTRY_CANDIDATES if c not in candidates]
    for c in candidates:
        if os.path.isfile(os.path.join(folder, c)):
            return folder_name + '/' + c
    return None


def module_embed_src(module_id, output_path, modules_dir=None, modules_url=None):
    """Iframe src for a module, or None to keep the placeholder.

    modules_dir: folder holding mirrored modules; the module must exist there.
    modules_url: public URL prefix of that folder. With modules_dir it only changes
                 the src; on its own every module is assumed to be hosted there.
    """
    if modules_dir:
        entry = find_module_entry(modules_dir, module_id)
        if not entry:
            return None
    elif modules_url and safe_module_folder(module_id):
        entry = safe_module_folder(module_id) + '/story.html'
    else:
        return None
    if modules_url:
        return modules_url.rstrip('/') + '/' + url_quote(entry, safe='/')
    rel = os.path.relpath(os.path.join(modules_dir, entry), os.path.dirname(os.path.abspath(output_path)))
    return rel.replace(os.sep, '/')

